blockquote.background-image:
linear-gradient(
    to right,
    transparent var(--blockquote-rail-gap),
    var(--blockquote-rail-secondary-color) var(--blockquote-rail-gap),
    var(--blockquote-rail-secondary-color) calc(var(--blockquote-rail-gap) + var(--blockquote-rail-secondary-thickness)),
    transparent calc(var(--blockquote-rail-gap) + var(--blockquote-rail-secondary-thickness))
  )
